Here is the commit message:
net: libwx: fix VF illegal register access

Register WX_CFG_PORT_ST is a PF restricted register. When a VF is
initialized, attempting to read this register triggers an illegal
register access, which lead to a system hang.

When the device is VF, the bus function ID can be obtained directly from
the PCI_FUNC(pdev->devfn).

Fixes: a04ea57aae37 ("net: libwx: fix device bus LAN ID")
Cc: stable@vger.kernel.org
Signed-off-by: Jiawen Wu <jiawenwu@trustnetic.com>
Link: https://patch.msgid.link/4D1F4452D21DE107+20260429083743.88961-1-jiawenwu@trustnetic.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The original code unconditionally read the PF-restricted register WX_CFG_PORT_ST to obtain the bus function ID. For a VF device, this read is illegal and causes a system hang. The code did not check whether the device is a VF before accessing the register.

Here is the patch:

 int wx_sw_init(struct wx *wx)
 {
 	struct pci_dev *pdev = wx->pdev;
 	u32 ssid = 0;
 	int err = 0;

 	wx->vendor_id = pdev->vendor;
 	wx->device_id = pdev->device;
 	wx->revision_id = pdev->revision;
 	wx->oem_svid = pdev->subsystem_vendor;
 	wx->oem_ssid = pdev->subsystem_device;
 	wx->bus.device = PCI_SLOT(pdev->devfn);
-	wx->bus.func = FIELD_GET(WX_CFG_PORT_ST_LANID,
-				 rd32(wx, WX_CFG_PORT_ST));
+	if (pdev->is_virtfn)
+		wx->bus.func = PCI_FUNC(pdev->devfn);
+	else
+		wx->bus.func = FIELD_GET(WX_CFG_PORT_ST_LANID,
+					 rd32(wx, WX_CFG_PORT_ST));

 	if (wx->oem_svid == PCI_VENDOR_ID_WANGXUN ||
 	    pdev->is_virtfn) {
 		wx->subsystem_vendor_id = pdev->subsystem_vendor;
 		wx->subsystem_device_id = pdev->subsystem_device;
 	} else {
 		err = wx_flash_read_dword(wx, 0xfffdc, &ssid);
 		if (err < 0) {
 			wx_err(wx, "read of internal subsystem device id failed\n");
 			return err;
 		}

 		wx->subsystem_device_id = swab16((u16)ssid);
 	}

 	err = wx_init_rss_key(wx);
 	if (err < 0) {
 		wx_err(wx, "rss key allocation failed\n");
 		return err;
 	}
 	wx->rss_flags = WX_RSS_FIELD_IPV4 | WX_RSS_FIELD_IPV4_TCP |
 			WX_RSS_FIELD_IPV6 | WX_RSS_FIELD_IPV6_TCP;

 	wx->mac_table = kzalloc_objs(struct wx_mac_addr,
 				     wx->mac.num_rar_entries);
 	if (!wx->mac_table) {
 		wx_err(wx, "mac_table allocation failed\n");
 		kfree(wx->rss_key);
 		return -ENOMEM;
 	}

 	spin_lock_init(&wx->hw_stats_lock);
 	mutex_init(&wx->reset_lock);
 	bitmap_zero(wx->state, WX_STATE_NBITS);
 	bitmap_zero(wx->flags, WX_PF_FLAGS_NBITS);
 	wx->misc_irq_domain = false;

 	return 0;
 }
 EXPORT_SYMBOL(wx_sw_init);


